"""Lower bounds for e(S) on the cross from the subgroup generated by the
kernel K and parabolics in a few directions. Usage: python3 -B sub.py b"""
import sys, time, os
from surf import Room, iso, vertex_map, orbit_pairs, check_affine
from run import cross, parabolic, name
t0 = time.process_time()
b = int(sys.argv[1])
room = Room(cross(b))
out = []
log = lambda s: (print(s), out.append(s))
log(f'== cross b={b} subgroup: area {len(room.cells)}, M {room.N} squares')
mark = [1 if c else 0 for c in room.convex]
base = (room.h, room.v, room.tau, room.p0)
m0 = [k for k in range(room.N) if mark[room.p0[k]]]
gens = []
for s1 in m0:
    sig = iso(base, base, mark, m0[0], [s1])
    if sig is not None:
        gens.append(vertex_map(room, base, base, sig))
log(f'  |K| = {len(gens)}')
for word in ['', 'R', 'TR', 'TTR', 'RTR', 'TTTR', 'RTTR']:
    n, F = parabolic(room, word, 600, log)
    log(f'  parabolic W={word!r}: n={n}')
    if F is not None:
        check_affine(room, F)
        gens.append(F)
marks = [(6, 0), (0, 6), (5, 1), (6, 1), (3, 1), (1, 1), (0, 0), (1, 0)]
qc = room.qclass
for P in marks:
    s = room.vert((1, 1), P)
    orb = orbit_pairs(gens, (s, room.viota[s]))
    e = {qc(y) for x, y in orb if qc(x) == qc(s)}
    Gs = {qc(x) for x, _ in orb}
    log(f'  S={P}: subgroup |H.s|={len(Gs)}  e_H(S)={len(e)} (lower bound for e(S))')
log(f'  cpu {time.process_time() - t0:.1f}s')
open(os.path.join(os.path.dirname(os.path.abspath(__file__)), f'sub{b}.log'), 'w').write('\n'.join(out) + '\n')
